// Cut directly from the arm reference supplied by the user.
(function(root){const sources={"wave": "data:image/png;base64,", "idle": "data:image/png;base64,", "throw": "data:image/png;base64,", "bend": "data:image/png;base64,", "hold": "data:image/png;base64,"};const images={},cache=new Map();const F=root.FamilyArmArt={available:false};
F.ready=Promise.all(Object.entries(sources).map(([key,src])=>new Promise(resolve=>{const im=images[key]=new Image();im.onload=()=>resolve(true);im.onerror=()=>resolve(false);im.src=src;}))).then(results=>F.available=results.every(Boolean));
const pivots={wave:[77,330],idle:[72,72],throw:[74,80],bend:[72,64],hold:[75,230]};
F.draw=function(c,kind,x,y,s,color,mirror=1,rotation=0){if(!F.available)return false;const key=kind+color;let im=cache.get(key);if(!im){const source=images[kind];im=document.createElement('canvas');im.width=source.width;im.height=source.height;const g=im.getContext('2d');g.drawImage(source,0,0);const pixels=g.getImageData(0,0,im.width,im.height),d=pixels.data,n=parseInt(color.slice(1),16),rgb=[n>>16,(n>>8)&255,n&255];for(let i=0;i<d.length;i+=4){if(d[i+3]&&d[i+2]>d[i]*1.3&&d[i+2]>d[i+1]*1.15){const light=Math.max(.45,Math.min(1.2,d[i+2]/190));for(let k=0;k<3;k++)d[i+k]=Math.min(255,rgb[k]*light);}}g.putImageData(pixels,0,0);cache.set(key,im);}const p=pivots[kind];c.save();c.translate(x,y);c.rotate(rotation);c.scale(mirror*s*.07,s*.07);c.drawImage(im,-p[0],-p[1]);c.restore();return true;};})(window);
